definition.script:
pipeline {
  agent any

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '15'))
    timeout(time: 60, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/next_extra_primary.git'
      }
    }

    stage('Docker Preflight') {
      steps {
        sh '''
          docker version
          docker compose version
          curl -fsS -I http://localhost:5001/v2/ || true
          docker pull localhost:5001/johndoe6345789/businessplanner/businessplanner-base-conan:latest || true
        '''
      }
    }

    stage('Pull Service Images') {
      steps {
        sh '''
          docker compose pull --ignore-buildable || docker compose pull || true
        '''
      }
    }

    stage('Deploy Stack') {
      steps {
        sh '''
          set -e
          docker compose up -d --build --remove-orphans
        '''
      }
    }

    stage('Status') {
      steps {
        sh 'docker compose ps'
      }
    }
  }

  post {
    success {
      echo 'next_extra_primary stack deployed - portal: http://localhost:8889'
    }
    always {
      cleanWs()
    }
  }
}
